mapper.update:
UPDATE sol_preparation
SET status_code = #{update.statusCode},
    submitted_at = #{update.submittedAt},
    confirmed_at = #{update.confirmedAt},
    returned_at = #{update.returnedAt},
    return_reason = #{update.returnReason},
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.preparationId}
  AND version = #{update.expectedVersion}
  AND status_code = #{update.expectedStatusCode}

UPDATE sol_preparation
SET current_marker = NULL,
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.preparationId}
  AND version = #{update.expectedVersion}
  AND current_marker = 1

UPDATE sol_preparation
SET readiness_status_code = 'NOT_READY',
    snapshot_current = b'0',
    input_version = input_version + 1,
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.preparationId}
  AND version = #{update.expectedVersion}
  AND input_version = #{update.expectedInputVersion}
  AND readiness_version = #{update.expectedReadinessVersion}

UPDATE sol_preparation
SET readiness_status_code = #{update.readinessStatusCode},
    latest_readiness_snapshot_id = #{update.latestReadinessSnapshotId},
    snapshot_current = #{update.snapshotCurrent},
    readiness_version = readiness_version + 1,
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.preparationId}
  AND version = #{update.expectedVersion}
  AND input_version = #{update.expectedInputVersion}
  AND readiness_version = #{update.expectedReadinessVersion}
